// Isolated read-only replay of pinned native forward acceptance, for sparse pixels.
// Layout/arithmetic derived from Graphdeco renderer (research license in source).
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cub/cub.cuh>
#include <cstdint>
#include "cuda_rasterizer/rasterizer_impl.h"
using namespace CudaRasterizer;
GeometryState GeometryState::fromChunk(char*& c,size_t P){GeometryState g;obtain(c,g.depths,P,128);obtain(c,g.clamped,P*3,128);obtain(c,g.internal_radii,P,128);obtain(c,g.means2D,P,128);obtain(c,g.cov3D,P*6,128);obtain(c,g.conic_opacity,P,128);obtain(c,g.rgb,P*3,128);obtain(c,g.tiles_touched,P,128);cub::DeviceScan::InclusiveSum(nullptr,g.scan_size,g.tiles_touched,g.tiles_touched,P);obtain(c,g.scanning_space,g.scan_size,128);obtain(c,g.point_offsets,P,128);return g;}
ImageState ImageState::fromChunk(char*& c,size_t N){ImageState g;obtain(c,g.accum_alpha,N,128);obtain(c,g.n_contrib,N,128);obtain(c,g.ranges,N,128);return g;}
BinningState BinningState::fromChunk(char*& c,size_t P){BinningState g;obtain(c,g.point_list,P,128);obtain(c,g.point_list_unsorted,P,128);obtain(c,g.point_list_keys,P,128);obtain(c,g.point_list_keys_unsorted,P,128);cub::DeviceRadixSort::SortPairs(nullptr,g.sorting_size,g.point_list_keys_unsorted,g.point_list_keys,g.point_list_unsorted,g.point_list,P);obtain(c,g.list_sorting_space,g.sorting_size,128);return g;}
template<bool Write> __global__ void query_kernel(int Q,int W,const int* yx,const uint2* ranges,const uint32_t* list,const float2* means,const float4* conics,int64_t* counts,const int64_t* offsets,int* ids,float* weights,float* finalT){int q=blockIdx.x*blockDim.x+threadIdx.x;if(q>=Q)return;int y=yx[2*q],x=yx[2*q+1];uint2 range=ranges[(y/16)*((W+15)/16)+x/16];float T=1;int64_t count=0;
 for(uint32_t j=range.x;j<range.y;j++){int id=list[j];float2 xy=means[id];float2 d={xy.x-x,xy.y-y};float4 c=conics[id];float power=-.5f*(c.x*d.x*d.x+c.z*d.y*d.y)-c.y*d.x*d.y;if(power>0)continue;float alpha=min(.99f,c.w*exp(power));if(alpha<1.f/255.f)continue;float next=T*(1-alpha);if(next<.0001f)break;if(Write){int64_t k=offsets[q]+count;ids[k]=id;weights[k]=T*alpha;}count++;T=next;}
 counts[q]=count;finalT[q]=T;}
std::vector<torch::Tensor> query(torch::Tensor geom,torch::Tensor bin,torch::Tensor img,int P,int R,int H,int W,torch::Tensor pixels){TORCH_CHECK(pixels.is_cuda()&&pixels.scalar_type()==torch::kInt32&&pixels.is_contiguous()&&pixels.dim()==2&&pixels.size(1)==2,"CUDA int32 Qx2 pixels required");TORCH_CHECK(pixels.numel()==0 || (pixels.select(1,0).min().item<int>()>=0&&pixels.select(1,0).max().item<int>()<H&&pixels.select(1,1).min().item<int>()>=0&&pixels.select(1,1).max().item<int>()<W),"query outside image");char* a=(char*)geom.data_ptr();char* b=(char*)bin.data_ptr();char* c=(char*)img.data_ptr();auto g=GeometryState::fromChunk(a,P);auto bs=BinningState::fromChunk(b,R);auto is=ImageState::fromChunk(c,H*W);int Q=pixels.size(0);auto counts=torch::zeros({Q},pixels.options().dtype(torch::kInt64));auto ts=torch::ones({Q},pixels.options().dtype(torch::kFloat32));query_kernel<false><<<(Q+255)/256,256>>>(Q,W,pixels.data_ptr<int>(),is.ranges,bs.point_list,g.means2D,g.conic_opacity,counts.data_ptr<int64_t>(),nullptr,nullptr,nullptr,ts.data_ptr<float>());auto offsets=torch::cat({torch::zeros({1},counts.options()),counts.cumsum(0)});int64_t n=offsets[-1].item<int64_t>();auto ids=torch::empty({n},pixels.options());auto weights=torch::empty({n},ts.options());query_kernel<true><<<(Q+255)/256,256>>>(Q,W,pixels.data_ptr<int>(),is.ranges,bs.point_list,g.means2D,g.conic_opacity,counts.data_ptr<int64_t>(),offsets.data_ptr<int64_t>(),ids.data_ptr<int>(),weights.data_ptr<float>(),ts.data_ptr<float>());return {offsets,ids,weights,ts};}
std::vector<torch::Tensor> geometry(torch::Tensor geom,int P){char* a=(char*)geom.data_ptr();auto g=GeometryState::fromChunk(a,P);auto opts=geom.options().dtype(torch::kFloat32);auto xy=torch::empty({P,2},opts),cov=torch::empty({P,6},opts),conic=torch::empty({P,4},opts),rgb=torch::empty({P,3},opts);cudaMemcpy(xy.data_ptr(),g.means2D,P*2*sizeof(float),cudaMemcpyDeviceToDevice);cudaMemcpy(cov.data_ptr(),g.cov3D,P*6*sizeof(float),cudaMemcpyDeviceToDevice);cudaMemcpy(conic.data_ptr(),g.conic_opacity,P*4*sizeof(float),cudaMemcpyDeviceToDevice);cudaMemcpy(rgb.data_ptr(),g.rgb,P*3*sizeof(float),cudaMemcpyDeviceToDevice);return {xy,cov,conic,rgb};}
PYBIND11_MODULE(TORCH_EXTENSION_NAME,m){m.def("query",&query);m.def("geometry",&geometry);}
